  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Plaies.html&quot; title=&quot;Les plaies magiques&quot;&gt;Les plaies magiques&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Description-Des-Plaies-Magiques.html&quot; title=&quot;Description des plaies magiques&quot;&gt;descriptions individuelles&lt;/a&gt;)&lt;/li&gt;
